  const colorCol=cols.find(c=>idOf(c)==='color');
  const LIGHT=(colorCol.modes.find(m=>m.name==='light')||colorCol.modes[0]).modeId;
  const DARKm=colorCol.modes.find(m=>m.name==='dark')||colorCol.modes[1]; const DARK=DARKm?DARKm.modeId:null;
  const tS={}; for(const s of await figma.getLocalTextStylesAsync()) tS[idOf(s)]=s;
  const eS={}; for(const s of await figma.getLocalEffectStylesAsync()) eS[idOf(s)]=s;
  await figma.loadFontAsync({family:'Inter',style:'Regular'});
  const fk=f=>f.family+'|'+f.style; const loaded=new Set(['Inter|Regular']), tried=new Set();
  for(const s of Object.values(tS)){ const k=fk(s.fontName); if(tried.has(k)) continue; tried.add(k); try{ await figma.loadFontAsync(s.fontName); loaded.add(k);}catch(e){} }
